  const loadRegistrationPrefill = (patientId: string, details?: any) => {
    const registrationForm = module.forms.find((f) => f.id === "new_patient_registration");
    if (!registrationForm) return;
    const registrationFields = registrationForm.fields.some(
      (field) => isQueueField(field.key),
    )
      ? registrationForm.fields
      : [
          ...registrationForm.fields,
          {
            key: "queue_to_next_module",
            label: "Queue to Next Stage",
            type: "select" as const,
            required: true,
            options: nextQueueOptions,
          },
        ];
    const base = emptyForm(registrationFields);
    const backend = details
      ? prefillFromPatientDetails(details, registrationFields, false)
      : {};
    const fromRegistrationRecord = prefillFromModuleRecords(
      patientId,
      1,
      registrationFields,
      false,
    );
    const fromSnapshot = loadRegistrationSnapshot(patientId, registrationFields);
    setActiveFormId("new_patient_registration");
    setIsFormPopupOpen(true);
    setLockedPrefillFieldKeys(new Set());
    setForm({
      ...base,
      ...backend,
      ...fromRegistrationRecord,
      ...fromSnapshot,
    });
  };

