  const parseSecurityPermissionList = useCallback((raw: string) => {
    return Array.from(
      new Set(
        String(raw || "")
          .split(/[\n,;]+/)
          .flatMap((part) => part.split(/\s+/))
          .map((part) => part.trim().toUpperCase())
          .filter(Boolean),
      ),
    );
  }, []);

  const loadSecurityControlCenter = useCallback(async () => {
    if (!isSecurityModule) return;
    setSecurityLoading(true);
    setSecurityError("");
    try {
      const [posture, dashboard, policy, permissionCatalog, rbacCatalog, userRows, roleRows] =
        await Promise.all([
          fetchSecurityPosture(),
          fetchSecurityDashboard(),
          fetchSecurityPasswordPolicy(),
          fetchSecurityPermissionsCatalog(),
          fetchSecurityRbacCatalog(),
          fetchTenantUsers(),
          fetchTenantRoles(),
        ]);
      setSecurityPosture(posture || null);
      setSecurityDashboard(dashboard || null);
      setSecurityPasswordPolicy(policy || null);
      setSecurityRbacCatalog(rbacCatalog || null);
      setSecurityPermissionsCatalog(
        Array.isArray(permissionCatalog) ? permissionCatalog.map((row: any) => String(row)) : [],
      );
      setSecurityUsers(Array.isArray(userRows) ? userRows : []);
      setSecurityRoles(Array.isArray(roleRows) ? roleRows : []);

      if (!securityNewUserRoleName && Array.isArray(roleRows) && roleRows.length > 0) {
        const firstRoleId = String((roleRows as any[])[0]?.id || "");
        setSecurityNewUserRoleId((current) => current || firstRoleId);
      }
      const templates = Array.isArray((rbacCatalog as any)?.templates)
        ? ((rbacCatalog as any).templates as any[])
        : [];
      if (templates.length > 0) {
        const firstTemplateName = String(templates[0]?.name || "");
        setSecuritySelectedTemplateName((current) => current || firstTemplateName);
      }
      setSecurityPendingRoleByUser((previous) => {
        const next = { ...previous };
        (Array.isArray(userRows) ? userRows : []).forEach((row: any) => {
          const userId = String(row?.id || "");
          if (!userId) return;
          if (!next[userId]) {
            next[userId] = String(row?.roleId || "");
          }
        });
        return next;
      });
    } catch (error: any) {
      setSecurityError(
        String(error?.message || "Failed to load user management and security data."),
      );
    } finally {
      setSecurityLoading(false);
    }
  }, [isSecurityModule, securityNewUserRoleName]);

