  const posComputedTotals = useMemo(() => {
    const gross = posCart.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
    const lineDiscount = posCart.reduce(
      (sum, item) => sum + ((item.quantity * item.unitPrice) * Math.max(0, Math.min(item.discountPercent, 100))) / 100,
      0,
    );
    const subtotal = Math.max(0, gross - lineDiscount);
    const globalDiscountAmount = Number(posDiscountAmount || 0);
    const globalDiscountPercent = Number(posDiscountPercent || 0);
    const globalDiscount =
      Number.isFinite(globalDiscountAmount) && globalDiscountAmount > 0
        ? globalDiscountAmount
        : Number.isFinite(globalDiscountPercent) && globalDiscountPercent > 0
          ? (subtotal * Math.min(globalDiscountPercent, 100)) / 100
          : 0;
    const discountedSubtotal = Math.max(0, subtotal - globalDiscount);
    const taxPercent = Number.isFinite(Number(posTaxPercent)) ? Number(posTaxPercent) : 16;
    const taxAmount = (discountedSubtotal * Math.max(0, Math.min(taxPercent, 100))) / 100;
    const grossPayable = discountedSubtotal + taxAmount;
    const insuranceCoveragePercent = Number(posInsuranceCoveragePercent || 0);
    const insuranceCoveredAmount =
      Math.max(0, Math.min(insuranceCoveragePercent, 100)) > 0
        ? (discountedSubtotal * Math.min(Math.max(insuranceCoveragePercent, 0), 100)) / 100
        : 0;
    const payableAfterInsurance = Math.max(0, grossPayable - insuranceCoveredAmount);
    const coPayRaw = Number(posCoPayAmount || 0);
    const payableTarget =
      Number.isFinite(coPayRaw) && coPayRaw > 0
        ? Math.min(coPayRaw, payableAfterInsurance)
        : payableAfterInsurance;
    const paidRaw = Number(posPaidAmount || 0);
    const paidAmount = Number.isFinite(paidRaw) && paidRaw >= 0 ? paidRaw : payableTarget;
    const outstanding = Math.max(0, payableTarget - paidAmount);
    return {
      gross,
      lineDiscount,
      subtotal,
      globalDiscount,
      discountedSubtotal,
      taxPercent,
      taxAmount,
      grossPayable,
      insuranceCoveredAmount,
      payableTarget,
      paidAmount,
      outstanding,
    };
  }, [
    posCart,
    posDiscountAmount,
    posDiscountPercent,
    posTaxPercent,
    posInsuranceCoveragePercent,
    posCoPayAmount,
    posPaidAmount,
  ]);

