  const handleHrSaveStaff = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isHrModule) return;
    const name = hrStaffName.trim();
    const [firstName, ...lastParts] = name.split(/\s+/).filter(Boolean);
    const lastName = lastParts.join(" ");
    if (!firstName || !lastName) {
      setFormNotice({ type: "error", message: "Enter full staff name (first and last)." });
      return;
    }
    try {
      if (hrEditingStaffId) {
        await updateStaffProfile(hrEditingStaffId, {
          firstName,
          lastName,
          licenseNumber: hrStaffLicense || undefined,
          specialization: hrStaffSpec || undefined,
          phone: hrStaffPhone || undefined,
          email: hrStaffEmail || undefined,
          employmentStatus: hrStaffEmploymentStatus || undefined,
        });
        setFormNotice({ type: "success", message: "Staff profile updated." });
      } else {
        await createStaffProfile({
          firstName,
          lastName,
          licenseNumber: hrStaffLicense || undefined,
          specialization: hrStaffSpec || undefined,
          phone: hrStaffPhone || undefined,
          email: hrStaffEmail || undefined,
          employmentStatus: hrStaffEmploymentStatus || undefined,
          roleTitle: hrStaffRoleTitle || undefined,
        });
        setFormNotice({ type: "success", message: "Staff profile created." });
      }
      setHrEditingStaffId("");
      setHrStaffName("");
      setHrStaffLicense("");
      setHrStaffSpec("");
      setHrStaffPhone("");
      setHrStaffEmail("");
      setHrStaffEmploymentStatus("ACTIVE");
      setHrStaffRoleTitle("Nurse");
      await loadHrControlCenter();
    } catch (error: any) {
      setFormNotice({ type: "error", message: String(error?.message || "Failed to save staff profile.") });
    }
  };

